/// <summary>
/// PricingAttribute of table <c>WHSCustTable</c> field FulfillmentRate.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeWHSCustTableFulfillmentRate extends UPSPricingAttributeWHSCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSCustTable, FulfillmentRate);
}

public Set getAllowedValues()
{
    var          ret = new Set(Types::Real);
    WHSCustTable wHSCustTable;

    while select wHSCustTable
        group by FulfillmentRate
    {
        if (! ret.in(wHSCustTable.FulfillmentRate))
        {
            ret.add(wHSCustTable.FulfillmentRate);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSCustTable, FulfillmentRate));
    qbr.value(queryValue(_value));
}
